const DEFAULTS = { theme: "light", fontSize: 16 };
const THEMES = new Set(["light", "dark"]);

function loadPrefs() {
  let raw = null;
  try {
    raw = localStorage.getItem("prefs");              // may throw if storage is blocked.
  } catch {
    return { ...DEFAULTS };
  }
  if (raw === null) return { ...DEFAULTS };           // nothing saved yet.
  try {
    const data = JSON.parse(raw);
    return {
      theme: THEMES.has(data?.theme) ? data.theme : DEFAULTS.theme,
      fontSize: Number.isInteger(data?.fontSize) && data.fontSize >= 12 && data.fontSize <= 24
        ? data.fontSize : DEFAULTS.fontSize,
    };
  } catch {
    return { ...DEFAULTS };                           // corrupt JSON.
  }
}

function savePrefs(prefs) {
  try { localStorage.setItem("prefs", JSON.stringify(prefs)); }
  catch { /* quota or private mode: preferences just won't persist. */ }
}
